parameters.functionCode:
// Find Due Diligence tasks that need processing
const tasks = $input.first().json.result || [];
console.log(`Checking ${tasks.length} tasks for Due Diligence processing`);

// Look for tasks with "Due Diligence:" in title
for (const task of tasks) {
  const title = task.title ? task.title.toString() : '';
  const description = task.description ? task.description.toString() : '';

  // Check if it's a Due Diligence task
  if (title.toLowerCase().includes('due diligence:')) {
    // Extract company name from title
    const companyName = title.replace(/due diligence:\s*/i, '').trim();

    // Check if Due Diligence is already completely done
    if (description.includes('🤖 COMPLETE DUE DILIGENCE REPORT GENERATED')) {
      console.log(`Task ${task.id} already has complete Due Diligence - skipping`);
      continue;
    }

    // Get all section names that are already approved
    const approvedSectionMatches = description.match(/📋 \*\*(.*?)\*\* - ✅ APPROVED/g) || [];
    const approvedSectionNames = approvedSectionMatches.map(match => {
      const nameMatch = match.match(/📋 \*\*(.*?)\*\* - ✅ APPROVED/);
      return nameMatch ? nameMatch[1] : '';
    });

    console.log(`Task ${task.id}: ${approvedSectionNames.length}/15 sections completed`);
    console.log(`Approved sections: ${approvedSectionNames.join(', ')}`);

    // Define all sections in order
    const allSections = [
      "Executive Summary", "Company Overview", "Business Model Analysis",
      "Market Analysis", "Financial Performance", "Management Team",
      "Technology Assessment", "Operations Analysis", "Legal and Compliance",
      "Risk Assessment", "ESG Analysis", "Competitive Landscape",
      "Growth Prospects", "Valuation Analysis", "Investment Recommendation"
    ];

    // Find NEXT section to process (must be sequential)
    let nextSectionToProcess = null;
    let nextSectionIndex = -1;

    // Find the first section that hasn't been approved yet
    for (let i = 0; i < allSections.length; i++) {
      if (!approvedSectionNames.includes(allSections[i])) {
        nextSectionToProcess = allSections[i];
        nextSectionIndex = i;
        break;
      }
    }

    // If we found a section that needs processing
    if (nextSectionToProcess) {
      console.log(`✅ Found Due Diligence task needing processing: "${title}" (ID: ${task.id})`);
      console.log(`Processing section: ${nextSectionToProcess} (${nextSectionIndex + 1}/15)`);

      return {
        json: {
          task_id: task.id,
          title: title.trim(),
          company_name: companyName,
          description: description.trim(),
          project_id: task.project_id || 1,
          current_section_number: nextSectionIndex,
          next_section_name: nextSectionToProcess,
          completed_sections: approvedSectionNames.length,
          approved_section_names: approvedSectionNames,
          all_sections: allSections
        }
      };
    } else {
      // All sections done but workflow doesn't need to handle this here
      // Setup Sections will detect completion and trigger final report
      console.log(`✅ All sections completed for task ${task.id}, will generate final report`);
      return {
        json: {
          task_id: task.id,
          title: title.trim(),
          company_name: companyName,
          description: description.trim(),
          project_id: task.project_id || 1,
          current_section_number: 15,
          completed_sections: 15,
          all_sections: allSections,
          approved_section_names: approvedSectionNames
        }
      };
    }
  }
}

// If no tasks need processing, stop gracefully
console.log('ℹ️ No Due Diligence tasks need processing - workflow completed');
return { json: { workflow_complete: true, message: "No Due Diligence tasks found to process" } };

// Workflow stopped - no Due Diligence tasks found
const data = $input.first().json;
console.log('✅ Workflow completed successfully - no tasks to process');
return { json: { status: 'completed', message: data.message || 'No tasks found' } };

// Get task data and set up current section for Due Diligence report
const taskData = $input.first().json;

// Define the Due Diligence report sections
const sections = [
  {
    "name": "Executive Summary",
    "description": "High-level overview of the company and key findings"
  },
  {
    "name": "Company Overview",
    "description": "Basic company information, history, and structure"
  },
  {
    "name": "Business Model Analysis",
    "description": "Revenue streams, value proposition, and business strategy"
  },
  {
    "name": "Market Analysis",
    "description": "Industry overview, market size, competition, and positioning"
  },
  {
    "name": "Financial Performance",
    "description": "Revenue, profitability, cash flow, and financial health"
  },
  {
    "name": "Management Team",
    "description": "Leadership assessment, experience, and track record"
  },
  {
    "name": "Technology Assessment",
    "description": "Technology stack, IP, innovation capabilities"
  },
  {
    "name": "Operations Analysis",
    "description": "Operational efficiency, processes, and scalability"
  },
  {
    "name": "Legal and Compliance",
    "description": "Legal structure, compliance status, regulatory risks"
  },
  {
    "name": "Risk Assessment",
    "description": "Key risks and mitigation strategies"
  },
  {
    "name": "ESG Analysis",
    "description": "Environmental, Social, and Governance factors"
  },
  {
    "name": "Competitive Landscape",
    "description": "Competitor analysis and market positioning"
  },
  {
    "name": "Growth Prospects",
    "description": "Future growth opportunities and expansion plans"
  },
  {
    "name": "Valuation Analysis",
    "description": "Company valuation and financial metrics"
  },
  {
    "name": "Investment Recommendation",
    "description": "Final recommendation and rationale"
  }
];

// Check if we need to create final combined report
if (taskData.completed_sections >= 15) {
  console.log(`🎉 ALL 15 SECTIONS COMPLETED! Ready to generate final combined report for company: ${taskData.company_name}`);
  return {
    json: {
      ...taskData,
      all_sections_complete: true,
      total_sections: sections.length
    }
  };
}

// Get current section to process (ONE section at a time)
const currentSectionIndex = taskData.current_section_number;
const currentSection = sections[currentSectionIndex];

if (!currentSection) {
  throw new Error(`Section index ${currentSectionIndex} is out of range. Total sections: ${sections.length}`);
}

console.log(`🎯 PROCESSING SECTION ${currentSectionIndex + 1}/${sections.length}: ${currentSection.name} for company: ${taskData.company_name}`);
console.log(`📊 Progress: ${taskData.completed_sections}/${sections.length} sections completed`);

// Create output with task data and ONLY current section to process
return {
  json: {
    task_id: taskData.task_id,
    company_name: taskData.company_name,
    title: taskData.title,
    project_id: taskData.project_id,
    total_sections: sections.length,
    current_section_index: currentSectionIndex,
    current_section: currentSection,
    completed_sections: taskData.completed_sections,
    approved_section_names: taskData.approved_section_names || [],
    processing_single_section: true
  }
};

// Generate final combined Due Diligence report
const taskData = $input.first().json;

console.log(`🎉 Generating final combined Due Diligence report for: ${taskData.company_name}`);

// Get task description with all approved sections
const description = taskData.description || '';

// Extract all approved sections from the task description
const sectionRegex = /📋 \*\*(.*?)\*\* - ✅ APPROVED\n\n([\s\S]*?)\n\n---/g;
const sections = [];
let match;

while ((match = sectionRegex.exec(description)) !== null) {
  sections.push({
    name: match[1],
    content: match[2].trim()
  });
}

console.log(`Found ${sections.length} approved sections to combine`);

// Create comprehensive final report
let finalReport = `# 📊 DUE DILIGENCE REPORT\n\n**Company:** ${taskData.company_name}\n**Report Generated:** ${new Date().toISOString()}\n**Sections Completed:** ${sections.length}/15\n\n---\n\n`;

// Add each section to the final report
sections.forEach((section, index) => {
  finalReport += `## ${index + 1}. ${section.name}\n\n${section.content}\n\n---\n\n`;
});

// Add final summary
finalReport += `\n## 📋 EXECUTIVE SUMMARY\n\nThis comprehensive Due Diligence report has been generated through an AI-powered Maker-Checker-Approver process, ensuring quality and accuracy at every step.\n\n**Key Highlights:**\n- All ${sections.length} sections completed and approved\n- Content validated through rigorous MCA process\n- Ready for investment decision-making\n\n**Report Status:** ✅ COMPLETE\n**Quality Assurance:** Triple-validated (Maker → Checker → Approver)\n\n---\n\n*This report was generated using advanced AI systems with human-level quality controls.*`;

return {
  json: {
    task_id: taskData.task_id,
    company_name: taskData.company_name,
    final_report: finalReport,
    sections_count: sections.length,
    report_ready: true
  }
};

