try {
  const jsonMatch = approverResponse.match(/\{[\s\S]*?\}/);
  if (jsonMatch) {
    approverData = JSON.parse(jsonMatch[0]);
  } else {
    approverData = {
      approved: true,
      final_feedback: "Section approved",
      suggestions: "None"
    };
  }
} catch (error) {
  console.log(`Approver JSON parsing failed: ${error.message}`);
  approverData = {
    approved: true,
    final_feedback: "Section approved",
    suggestions: "None"
  };
}

console.log(`Approver result: ${approverData.approved ? 'APPROVED' : 'REJECTED'}`);

return {
  json: {
    ...sectionData,
    approver_approved: approverData.approved,
    approver_feedback: approverData.final_feedback,
    approver_suggestions: approverData.suggestions
  }
};

